mapper.select:
SELECT
FROM gc_event AS e LEFT JOIN gc_user u on e.upload_user=u.id LEFT JOIN gc_user_info ui on ui.id=u.info_id LEFT JOIN gc_user_answer AS ua ON ua.event_id = e.id LEFT JOIN gc_user_event AS ue ON ue.event_id = e.id WHERE e.video_id = #{vid} AND ua.user_id = #{userId}
AND (ue.user_id = #{userId} OR e.upload_type != 2)

SELECT
FROM gc_event AS e LEFT JOIN gc_user u on e.upload_user=u.id LEFT JOIN gc_user_info ui on ui.id=u.info_id LEFT JOIN gc_user_answer AS ua ON ua.event_id = e.id and ua.master_id=#{masterId} LEFT JOIN gc_user_event AS ue ON ue.event_id = e.id WHERE e.video_id in
#{vid}
AND ua.user_id = #{userId}
AND (ue.user_id = #{userId} OR e.upload_type != 2)

SELECT


,ua.id as ua_id, ua.answer_json as ua_answerJson, ua.update_time as ua_updateTime,
CASE WHEN ua.answer_json is null THEN 0 ELSE 1 END as myAnswerFlag
FROM
gc_event AS e
LEFT JOIN gc_user u on e.upload_user=u.id
LEFT JOIN gc_user_info ui on ui.id=u.info_id
LEFT JOIN gc_user_answer AS ua ON ua.event_id = e.id and ua.master_id=#{masterId}

    AND ua.user_id = #{userId}

LEFT JOIN gc_user_event AS ue ON ue.event_id = e.id and ue.master_id=#{masterId}
WHERE e.video_id = #{vid} AND ue.user_id = #{userId}

or (e.video_id=#{vid} and e.upload_type != 2  )
order by e.event_time

SELECT
DISTINCT E.ID, E.VIDEO_ID , E.UPLOAD_TYPE, UA.ANSWER_JSON::jsonb,v.sub_id as subjectId,
s.sub_id as subId,UA.create_time as answerCreateTime,
ua.update_time as updateTime,
UA.id as myAnswerId
FROM GC_EVENT E
LEFT JOIN GC_USER_EVENT UE ON UE.EVENT_ID = E.ID AND UE.user_id=#{userId}
LEFT JOIN GC_USER_ANSWER UA ON UA.EVENT_ID=E.ID AND UA.master_id=#{masterId}
left join gc_video v on v.id = e.video_id
left join gc_subject s on s.id = v.sub_id

AND UA.USER_ID = #{userId}

WHERE
UE.master_id=#{masterId} AND UA.USER_ID = #{userId}

    AND E.VIDEO_ID IN

        #{videoId}


 or (E.UPLOAD_TYPE != 2 and  UA.USER_ID = #{userId}

     and E.VIDEO_ID IN

     #{videoId}

 )

SELECT
DISTINCT E.ID, E.VIDEO_ID , E.UPLOAD_TYPE, UA.ANSWER_JSON::jsonb,v.sub_id as subjectId,
s.sub_id as subId,ue.user_id as userId
FROM GC_EVENT E
LEFT JOIN GC_USER_EVENT UE ON UE.EVENT_ID = E.ID

    AND UE.user_id=#{userId}

LEFT JOIN GC_USER_ANSWER UA ON UA.EVENT_ID=E.ID AND UA.master_id=#{masterId}
left join gc_video v on v.id = e.video_id
left join gc_subject s on s.id = v.sub_id

    AND UA.USER_ID = #{userId}

WHERE
UE.master_id=#{masterId}

    AND UA.USER_ID = #{userId}


    AND E.VIDEO_ID IN

        #{videoId}


or (E.UPLOAD_TYPE != 2

    and  UA.USER_ID = #{userId}


and E.VIDEO_ID IN

    #{videoId}

    )

SELECT
DISTINCT E.ID, E.VIDEO_ID , E.UPLOAD_TYPE, UA.ANSWER_JSON::jsonb,v.sub_id as subjectId,
s.sub_id as subId
FROM GC_EVENT E
LEFT JOIN GC_USER_EVENT UE ON UE.EVENT_ID = E.ID AND UE.user_id=#{userId}
LEFT JOIN GC_USER_ANSWER UA ON UA.EVENT_ID=E.ID
left join gc_video v on v.id = e.video_id
left join gc_subject s on s.id = v.sub_id

    AND UA.USER_ID = #{userId}

WHERE
UE.master_id=#{masterId}
    AND UA.USER_ID = #{userId}

    AND E.VIDEO_ID IN

        #{videoId}


or (E.UPLOAD_TYPE != 2 and  UA.USER_ID = #{userId}

    and E.VIDEO_ID IN

    #{videoId}
 )

select s.sub_id from gc_event e LEFT JOIN gc_video v on e.video_id=v.id LEFT JOIN gc_subject s on s.id=v.sub_id WHERE e.id in
#{eid}
GROUP BY s.sub_id

	    SELECT e.id as eventId,
		count(ua.event_id) as answerNum
		FROM   gc_event AS e
		LEFT JOIN gc_user_event AS ue ON ue.event_id = e.id and ue.master_id=#{masterId}
		left join gc_user_answer as ua on ua.event_id = e.id and ua.master_id=#{masterId}
		WHERE  e.video_id = #{vid}

            and  ue.user_id = #{userId}

	   or ( e.video_id = #{vid} and e.upload_type != 2 )
	         group by ua.event_id, e.id
	         order by e.event_time

select count(1) from gc_event
where video_id in
#{list}

select distinct e.id,e.upload_user,e.video_id,e.event_time,e.event_title,e.time_limit,e.event_type,e.ext::jsonb,e.upload_type ,e.link_file_id,e.link_video_id,video.video_name as videoName,sub1.name as sub1Name,sub0.name as sub0Name,count(message.id) as unreadMessages ,max(answer.update_time) as lastAnswerTime from gc_event e left join gc_video video on video.id=e.video_id left join gc_subject sub1 on sub1.id = video.sub_id left join gc_subject sub0 on sub0.id = sub1.fid left join gc_user_answer answer on answer.event_id = e.id left join gc_master_message message on message.user_answer_id=answer.id and message.target_user_id=#{userId} where answer.master_id = #{masterId} and message.read_state=0 and sub0.id in
#{subId}
AND sub1.id in
#{sub1Id}
AND video.id in
#{videoId}
group by e.id, e.upload_user, e.video_id, e.event_time, e.event_title, e.time_limit, e.event_type, e.ext::jsonb, e.upload_type, e.link_file_id, e.link_video_id, video.video_name, sub1.name, sub0.name
order by max(answer.update_time) ${order}
order by max(answer.update_time) desc

select DISTINCT ON (ua.user_id, e.id) E.ID, E.VIDEO_ID , E.UPLOAD_TYPE, UA.ANSWER_JSON,ua.user_id, v.sub_id as subjectId, s.sub_id as subId FROM GC_EVENT E LEFT JOIN GC_USER_EVENT UE ON UE.EVENT_ID = E.ID LEFT JOIN GC_USER_ANSWER UA ON UA.EVENT_ID=E.ID left join gc_video v on v.id = e.video_id left join gc_subject s on s.id = v.sub_id
AND UA.USER_ID in
#{userId}
WHERE UE.master_id=#{masterId}
AND E.VIDEO_ID IN
#{videoId}
or (E.UPLOAD_TYPE != 2
and E.VIDEO_ID IN
#{videoId}
) and UA.ANSWER_JSON is not null

SELECT E.ID, E.VIDEO_ID, E.UPLOAD_TYPE, null as ANSWER_JSON, vo.sub_id FROM GC_EVENT E LEFT JOIN GC_USER_EVENT UE ON UE.EVENT_ID = E.ID LEFT JOIN GC_USER_ANSWER UA ON UA.EVENT_ID = E.ID left join gc_video vo on vo.id = e.video_id where ue.master_id = #{masterId}
AND E.VIDEO_ID IN
#{videoId}
or (E.UPLOAD_TYPE != 2
and E.VIDEO_ID IN
#{videoId}
) GROUP BY e.id,vo.sub_id

select E.ID, E.VIDEO_ID , E.UPLOAD_TYPE, UA.ANSWER_JSON,ua.user_id from GC_SUBJECT s left join gc_subject s2 on s2.fid = s.id left join gc_video v on v.sub_id = s2.id left join gc_event e on e.video_id = v.id LEFT JOIN GC_USER_EVENT UE ON UE.EVENT_ID = E.ID LEFT JOIN GC_USER_ANSWER UA ON UA.EVENT_ID=E.ID and ua.user_id in
#{user}
where s.id = #{subjectId} and e.id is not null and s.master_id = #{masterId}
